WITH filtered_payments AS (SELECT * FROM payments WHERE status IN ('FAILED', 'SUCCESS', 'REFUNDED')), summary AS (SELECT status, CASE WHEN amount >= 1750 THEN 'high' WHEN amount >= 750 THEN 'mid' ELSE 'low' END amount_bucket, ROUND(STDDEV(amount), 2) stddev_amount, MIN(paid_at) min_paid_at FROM filtered_payments GROUP BY status, CASE WHEN amount >= 1750 THEN 'high' WHEN amount >= 750 THEN 'mid' ELSE 'low' END) SELECT status, amount_bucket, stddev_amount, min_paid_at FROM summary ORDER BY 2 DESC, min_paid_at ASC;
